package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ValueInstantiator;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.Mockito.verify;

/**
 * Unit tests for AtomicReferenceDeserializer.getNullValue
 */
public class AtomicReferenceDeserializer_getNullValue_TriageGen0Test {

    private AtomicReferenceDeserializer deserializer;

    @Mock
    private DeserializationContext ctxt;

    @Mock
    private JavaType fullType;

    @Mock
    private ValueInstantiator inst;

    @Mock
    private com.fasterxml.jackson.databind.deser.TypeDeserializer typeDeser;

    @Mock
    private JsonDeserializer<?> deser;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        deserializer = new AtomicReferenceDeserializer(fullType, inst, typeDeser, deser);
    }

    @Test
    public void testGetNullValueReturnsNewAtomicReference() throws Exception {
        // Act
        AtomicReference<Object> result = deserializer.getNullValue(ctxt);

        // Assert
        Assert.assertNotNull("The returned AtomicReference should not be null", result);
        // Since the implementation returns a new AtomicReference<Object>(), 
        // we check if it is indeed an instance of AtomicReference.
        Assert.assertTrue("The result should be an instance of AtomicReference", result instanceof AtomicReference);

        // Verify that the context was passed (though not used in the current implementation, 
        // it ensures the method signature is respected).
        // In this specific implementation, ctxt is not accessed, so no interaction is expected.
    }

    @Test
    public void testGetNullValueIsIndependent() throws Exception {
        // Act
        AtomicReference<Object> ref1 = deserializer.getNullValue(ctxt);
        AtomicReference<Object> ref2 = deserializer.getNullValue(ctxt);

        // Assert
        Assert.assertNotNull(ref1);
        Assert.assertNotNull(ref2);
        Assert.assertNotSame("Each call to getNullValue should return a new instance", ref1, ref2);
    }
}
